{
  "version": 1,
  "_comment": "Managed scheduled jobs. The reconciler (scripts/keystone-reconcile.ps1) re-runs any job that has not succeeded today. Path tokens: {REPO}, {USERPROFILE}, {DEV}. successProbe lets the reconciler detect success from a job's own log, so jobs not routed through run-job.ps1 are still handled correctly. Set reconcile:false to leave a job to its scheduled trigger alone.",
  "jobs": [
    {
      "id": "morning-cadence",
      "label": "KeystoneOS morning cadence",
      "taskName": "KeystoneOS Morning",
      "exe": "pwsh",
      "script": "{REPO}/scripts/morning-cadence.ps1",
      "schedule": {
        "kind": "weekdays",
        "at": "06:00"
      },
      "graceMinutes": 45,
      "timeoutMinutes": 30,
      "maxAttemptsPerDay": 3,
      "reconcile": true,
      "successProbe": {
        "kind": "fileContains",
        "path": "{REPO}/outputs/morning/cadence.log",
        "pattern": "/[{DATE}T[^/]]*/] cadence OK"
      }
    },
    {
      "id": "daily-backup",
      "label": "Daily memory + repo backup",
      "taskName": "KeystoneOS-DailyBackup",
      "exe": "pwsh",
      "script": "{USERPROFILE}/.claude/scripts/daily-backup.ps1",
      "schedule": {
        "kind": "daily",
        "at": "00:30"
      },
      "graceMinutes": 60,
      "timeoutMinutes": 240,
      "maxAttemptsPerDay": 2,
      "reconcile": true,
      "makeupWindow": {
        "from": "07:00",
        "to": "20:00"
      },
      "successProbe": {
        "kind": "fileContains",
        "path": "{USERPROFILE}/.claude/scripts/logs/daily-backup.log",
        "pattern": "^{DATE} .*daily-backup end: OK"
      }
    },
    {
      "id": "stack-doctor",
      "label": "Weekly automation stack health check",
      "taskName": "KeystoneOS-StackDoctor",
      "exe": "pwsh",
      "script": "{USERPROFILE}/.claude/skills/claude-stack-doctor/scripts/weekly-check.ps1",
      "schedule": {
        "kind": "weekly",
        "dayOfWeek": "Monday",
        "at": "10:30"
      },
      "graceMinutes": 60,
      "timeoutMinutes": 30,
      "maxAttemptsPerDay": 2,
      "reconcile": true,
      "successProbe": {
        "kind": "fileModifiedToday",
        "path": "{USERPROFILE}/.claude/skills/claude-stack-doctor/scripts/last-weekly-run.log"
      }
    }
  ]
}
